// Gear art is split into bands by level. The base poses and the early gear bands load with this script and the
// loading screen; the other bands load in the background in level order (see loader.js). Each band is a script of
// data URLs, so it still works on file:// pages.
const HERO_ART_EARLY_BANDS = ['lv0', 'lv1', 'lv10'];
const HERO_ART_LATER_BANDS = ['lv20', 'lv30', 'lv40', 'lv50', 'lv60', 'lv70', 'lv80', 'lv90', 'lv99'];
function loadHeroArtBand(band) {
    return new Promise(resolve => {
        const s = document.createElement('script');
        s.src = 'js/hero-art/' + band + '.js?v=20261112c';
        s.onload = () => { if (typeof heroBodyAttachArt === 'function') heroBodyAttachArt(); resolve(); };
        s.onerror = () => resolve(); // a missing band should not block the game; its gear just stays hidden
        document.head.appendChild(s);
    });
}
function loadHeroArtBands(bands) {
    return bands.reduce((chain, band) => chain.then(() => loadHeroArtBand(band)), Promise.resolve());
}
